      "causa_raiz": "Tempo de renderização de GPU excessivo (36.11ms contra o teto de 16.67ms), agravado por sobrecarga de sombreamento (pixel/fragment shader), excesso de luzes dinâmicas com cálculo de sombras em tempo real, sobreposição de geometrias transparentes (overdraw) e falta de gerenciamento de resolução/níveis de detalhe (LOD).",
      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class PerformanceQualityManager : MonoBehaviour
{
    [Header("Ajustes de Renderização")]
    [SerializeField] private bool habilitarSombrasDinamicas = false;
    [SerializeField] private ShadowQuality qualidadeSombra = ShadowQuality.HardOnly;
    [SerializeField] private float distanciaSombra = 35f;
    [SerializeField] private float escalaResolucao = 0.85f;

    private void Awake()
    {
        AplicarConfiguracoesGraficas();
    }

    public void AplicarConfiguracoesGraficas()
    {
        // Reduz a distância de renderização de sombras dinâmicas para poupar GPU
        QualitySettings.shadowDistance = distanciaSombra;
        QualitySettings.shadows = habilitarSombrasDinamicas ? qualidadeSombra : ShadowQuality.Disable;
        QualitySettings.shadowCascades = 1;

        // Limita anisotropic filtering para aliviar a banda de memória da GPU
        QualitySettings.anisotropicFiltering = AnisotropicFiltering.Enable;
        Texture.SetGlobalAnisotropicFilteringLimits(2, 4);

        // Ajusta escala dinâmica de resolução para desafogar fragment shaders
        if (ScalableBufferManager.widthScaleFactor > 0)
        {
            ScalableBufferManager.ResizeBuffers(escalaResolucao, escalaResolucao);
        }
    }
}",
      "explicacao_didatica": "A placa de vídeo (GTX 1650) está demorando mais que o dobro do tempo permitido por quadro (36ms em vez de 16.6ms). Isso ocorre porque ela precisa calcular a cor de muitos pixels ao mesmo tempo, frequentemente repintando a mesma área da tela várias vezes (overdraw) e calculando luzes e sombras pesadas em tempo real. O código ajusta as opções globais de qualidade, reduzindo o alcance das sombras e ajustando a escala do buffer, aliviando o esforço da placa gráfica."
    },
    {
      "tipo": "DrawCalls",
      "causa_raiz": "Pico de 2791 Draw Calls ultrapassando o orçamento de 2579. O excesso de chamadas de desenho ocorre devido à falta de agrupamento de malhas (static/dynamic batching), múltiplos materiais independentes e ausência de instanciamento de GPU (GPU Instancing).",
      "codigo_refatorado": "using UnityEngine;

public class BatchingEnabler : MonoBehaviour
{
    [SerializeField] private Material materialInstanciado;

    private void Awake()
    {
        // Habilita GPU Instancing via código caso o material suporte
        if (materialInstanciado != null && !materialInstanciado.enableInstancing)
        {
            materialInstanciado.enableInstancing = true;
        }
    }

    // Combina estaticamente malhas de objetos filhos para diminuir Draw Calls
    [ContextMenu("Combinar Malhas Filhas")]
    public void CombinarMalhas()
    {
        MeshFilter[] filtros = GetComponentsInChildren<MeshFilter>();
        CombineInstance[] combinacoes = new CombineInstance[filtros.Length];

        for (int i = 0; i < filtros.Length; i++)
        {
            combinacoes[i].mesh = filtros[i].sharedMesh;
            combinacoes[i].transform = filtros[i].transform.localToWorldMatrix;
            filtros[i].gameObject.SetActive(false);
        }

        MeshFilter meuFiltro = gameObject.AddComponent<MeshFilter>();
        meuFiltro.mesh = new Mesh();
        meuFiltro.mesh.CombineMeshes(combinacoes, true, true);
        gameObject.SetActive(true);
    }
}",
      "explicacao_didatica": "Draw Calls são como pedidos que o processador (CPU) faz para a placa de vídeo desenhar objetos. Quanto mais objetos separados com materiais diferentes existirem, mais pedidos são feitos. Ao habilitar o 'GPU Instancing' e combinar malhas próximas, a placa gráfica consegue desenhar centenas de objetos semelhantes em uma única viagem, reduzindo os pedidos e mantendo a taxa de quadros estável."
    }
  ],
  "dicas_level_design": "1. Static Batching e Atlasing de Texturas: Combine texturas de objetos do cenário (props, paredes, pisos) em um único Texture Atlas para que compartilhem o mesmo material, permitindo que a Unity agrupe os Draw Calls automaticamente.
2. Occlusion Culling: Configure e asse (Bake) o Occlusion Culling na cena para garantir que objetos escondidos atrás de paredes ou montanhas não sejam enviados para a GPU renderizar.
3. LOD Groups (Level of Detail): Implemente grupos de LOD em objetos modulares. Elementos distantes devem ter geometrias simplificadas e desabilitar renderização de sombras.
4. Luzes e Baking: Converta luzes secundárias e de preenchimento de 'Realtime' para 'Baked' (Lightmapping), mantendo no máximo uma luz direcional em tempo real com sombras suaves limitadas em distância."
}

